-- Geiger Forms feature showcase: "Geiger Summit 2026 — Registration" (form 343ba6d4-7ee9-4a33-aa8c-f46e26e8d3c2) in the Geiger Notes project (ebcc7910-1a0e-4e91-8c3b-752f3c4292d3).
-- Exercises every field type and settings group: pages, logic, payments + coupons, booking, repeater, uploads, signature, scoring, branches, quiz, A/B test, approvals, automations, notifications, policy and attestation.
-- Also seeds 84 responses, funnel events, partials, bookings, versions, comments, activity and saved views. Deterministic ids, timestamps relative to now(); re-running restores the demo. Never ledgered.

do $guard$ begin
  if not exists (select 1 from public.projects where id = 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3') then
    raise exception 'Project ebcc7910-1a0e-4e91-8c3b-752f3c4292d3 does not exist';
  end if;
end $guard$;

-- Form (upserted by id so the existing form becomes the showcase)
on conflict (id) do update set project_id = excluded.project_id, slug = excluded.slug, title = excluded.title, description = excluded.description, status = excluded.status, category = excluded.category, tags = excluded.tags, schema = excluded.schema, settings = excluded.settings, is_template = excluded.is_template, created_at = excluded.created_at, updated_at = excluded.updated_at, published_at = excluded.published_at, deleted_at = null;

-- Responses (inserts bump forms.response_count via forms.sync_response_count)
on conflict (id) do update set answers = excluded.answers, respondent_name = excluded.respondent_name, respondent_email = excluded.respondent_email, status = excluded.status, priority = excluded.priority, score = excluded.score, submitted_at = excluded.submitted_at, updated_at = excluded.updated_at, user_agent = excluded.user_agent, completion_ms = excluded.completion_ms, tags = excluded.tags, assignee = excluded.assignee, outcome = excluded.outcome, metadata = excluded.metadata, approval = excluded.approval, payment_status = excluded.payment_status, payment_amount = excluded.payment_amount, payment_currency = excluded.payment_currency, payment_ref = excluded.payment_ref, deleted_at = null;

-- Booked 1:1 slots (so taken slots disappear from the public picker)
on conflict (id) do update set slot_start = excluded.slot_start, slot_end = excluded.slot_end, email = excluded.email, created_at = excluded.created_at, deleted_at = null;

-- Funnel events (view → start → submit), split across the two A/B variants
on conflict (id) do update set variant = excluded.variant, created_at = excluded.created_at;
on conflict (id) do update set variant = excluded.variant, created_at = excluded.created_at;

-- Abandoned partial submissions (save & resume)
on conflict (id) do update set answers = excluded.answers, last_field_id = excluded.last_field_id, page_index = excluded.page_index, progress = excluded.progress, created_at = excluded.created_at, updated_at = excluded.updated_at, completed_at = null, deleted_at = null;

-- Version history
on conflict (form_id, version) do update set label = excluded.label, author = excluded.author, notes = excluded.notes, schema = excluded.schema, settings = excluded.settings, created_at = excluded.created_at;

-- Internal comments
on conflict (id) do update set response_id = excluded.response_id, author = excluded.author, body = excluded.body, created_at = excluded.created_at;

-- Workspace activity
on conflict (id) do update set response_id = excluded.response_id, actor_name = excluded.actor_name, action = excluded.action, detail = excluded.detail, created_at = excluded.created_at;

-- Saved inbox views for this form
on conflict (id) do update set name = excluded.name, layout = excluded.layout, filters = excluded.filters, deleted_at = null;
