insert into forms.forms (id, project_id, slug, title, description, status, category, tags, schema, settings, is_template, created_at, updated_at, published_at, deleted_at) values
  ('343ba6d4-7ee9-4a33-aa8c-f46e26e8d3c2', 'ebcc7910-1a0e-4e91-8c3b-752f3c4292d3', 'geiger-forms-showcase', 'Geiger Summit 2026 — Registration', 'The Geiger Forms feature showcase: register for the summit, buy tickets, book a 1:1, plan the agenda and take a warm-up quiz. Every page demonstrates a different capability.', 'Published', 'Registration', array['showcase', 'events', 'payments'], $j${"fields":[{"label":"About you","required":false,"id":"h-about","type":"heading","title":"About you","hint":"Start with the basics. Every input validates as you type."},{"label":"Showcase note","required":false,"id":"n-welcome","type":"content","title":"Showcase note","hint":"This form is the Geiger Forms feature showcase. Each page highlights a different capability — look for notes like this one. The look itself (round corners, purple accent, gradient background and cover) is set in the builder Design panel.\n\nOn this page: name, email, phone, URL and number fields, half/third-width layouts, info tooltips, a read-only field prefilled from the link (?member=GS-1042) and hidden UTM fields."},{"label":"Full name","required":true,"id":"full-name","type":"name","title":"Full name"},{"label":"Work email","required":true,"id":"email","type":"email","title":"Work email","placeholder":"you@company.com","width":"half","info":"We send your tickets and calendar invites here. Duplicate registrations with the same email are flagged for review."},{"label":"Mobile number","required":false,"id":"phone","type":"phone","title":"Mobile number","placeholder":"+1 555 010 0100","width":"half","hint":"Only used for day-of-event updates."},{"label":"Company","required":true,"id":"company","type":"text","title":"Company","width":"half","validation":{"minLength":2,"maxLength":80}},{"label":"Company website","required":false,"id":"website","type":"url","title":"Company website","placeholder":"https://","width":"half"},{"label":"Your role","required":true,"id":"role","type":"dropdown","title":"Your role","options":["Engineering","Design","Product","Operations","Leadership","Other"],"width":"third"},{"label":"Team size","required":false,"id":"team-size","type":"number","title":"Team size","placeholder":"e.g. 25","width":"third","validation":{"min":1,"max":100000}},{"label":"Annual tooling budget","required":false,"id":"budget","type":"dropdown","title":"Annual tooling budget","options":["Under $10k","$10k–$50k","$50k–$100k","$100k+"],"width":"third","info":"Each option carries lead-scoring points.","optionPoints":{"Under $10k":0,"$10k–$50k":15,"$50k–$100k":30,"$100k+":50}},{"label":"Have you attended a Geiger Summit before?","required":true,"id":"attended-before","type":"select","title":"Have you attended a Geiger Summit before?","options":["Yes","No"]},{"label":"Member ID","required":false,"id":"member-id","type":"text","title":"Member ID","readOnly":true,"prefillKey":"member","hint":"Read-only — prefilled from the invite link (?member=…)."},{"label":"UTM source","required":false,"id":"utm-source","type":"hidden","title":"UTM source","prefillKey":"utm_source","defaultValue":"direct"},{"label":"UTM campaign","required":false,"id":"utm-campaign","type":"hidden","title":"UTM campaign","prefillKey":"utm_campaign"},{"label":"Tickets","required":false,"id":"page-tickets","type":"page","title":"Tickets"},{"label":"Payments note","required":false,"id":"n-payments","type":"content","title":"Payments note","hint":"Payments: products feed a live order total, and coupons are applied at checkout — try EARLYBIRD (15% off) or TEAM50 ($50 off). Checkout runs through Stripe when it's configured."},{"label":"General admission","required":false,"id":"ticket-ga","type":"product","title":"General admission","config":{"price":299,"quantityMode":"input","maxQuantity":5,"description":"Two days of talks, the expo hall, lunch and the closing party."}},{"label":"VIP pass","required":false,"id":"ticket-vip","type":"product","title":"VIP pass","config":{"price":799,"quantityMode":"fixed","maxQuantity":1,"description":"Front-row seating, speaker dinner and a private roadmap session."}},{"label":"Will you join the speaker dinner?","required":false,"id":"vip-dinner","type":"select","title":"Will you join the speaker dinner?","options":["Yes, count me in","No, thanks"],"hint":"Only shown when the VIP pass is selected — conditional logic.","conditions":[{"id":"c-vip","fieldId":"ticket-vip","operator":"equals","value":"true"}]},{"label":"Workshop pass","required":false,"id":"workshop-pass","type":"product","title":"Workshop pass","config":{"price":149,"quantityMode":"input","maxQuantity":3,"description":"Half-day, hands-on session with the Geiger team. Limited seats."}},{"label":"Scholarship fund donation","required":false,"id":"donation","type":"currency","title":"Scholarship fund donation","placeholder":"0.00","hint":"Optional. 100% funds tickets for students.","validation":{"min":0,"max":5000},"config":{"currency":"usd"}},{"label":"Order summary","required":false,"id":"order-total","type":"total","title":"Order summary"},{"label":"Logistics","required":false,"id":"page-logistics","type":"page","title":"Logistics"},{"label":"How will you attend?","required":true,"id":"attendance","type":"select","title":"How will you attend?","options":["In person","Online"]},{"label":"Arrival date","required":false,"id":"arrival-date","type":"date","title":"Arrival date","width":"half","conditions":[{"id":"c-ip1","fieldId":"attendance","operator":"equals","value":"In person"}]},{"label":"Estimated arrival time","required":false,"id":"arrival-time","type":"time","title":"Estimated arrival time","width":"half","conditions":[{"id":"c-ip2","fieldId":"attendance","operator":"equals","value":"In person"}]},{"label":"Shipping address for your welcome pack","required":false,"id":"address","type":"address","title":"Shipping address for your welcome pack","conditions":[{"id":"c-ip3","fieldId":"attendance","operator":"equals","value":"In person"}]},{"label":"Dietary requirements","required":false,"id":"dietary","type":"multiselect","title":"Dietary requirements","options":["Vegetarian","Vegan","Gluten-free","Halal","Kosher","No restrictions"],"conditions":[{"id":"c-ip4","fieldId":"attendance","operator":"equals","value":"In person"}]},{"label":"Preferred livestream tech check","required":false,"id":"stream-test","type":"datetime","title":"Preferred livestream tech check","hint":"Online attendees get a 10-minute audio/video check.","conditions":[{"id":"c-on1","fieldId":"attendance","operator":"equals","value":"Online"}]},{"label":"Accessibility needs","required":false,"id":"accessibility","type":"textarea","title":"Accessibility needs","placeholder":"Anything that would make the event work better for you.","sensitive":true,"hint":"Marked sensitive: encrypted at rest, masked in the inbox, and every reveal is logged.","validation":{"maxLength":600}},{"label":"Book a 1:1","required":false,"id":"page-booking","type":"page","title":"Book a 1:1"},{"label":"Booking note","required":false,"id":"n-booking","type":"content","title":"Booking note","hint":"Booking slots: pick a 30-minute slot with a product specialist. Slots are generated from working hours and disappear once booked (capacity 1)."},{"label":"Meet a product specialist","required":false,"id":"booking","type":"booking","title":"Meet a product specialist","config":{"days":[1,2,3,4,5],"start":"09:00","end":"17:00","slotMinutes":30,"capacity":1,"horizonDays":30,"leadHours":12,"timezone":"UTC"}},{"label":"What should we cover?","required":false,"id":"meeting-topic","type":"textarea","title":"What should we cover?","placeholder":"Your use case, questions, current tools…","conditions":[{"id":"c-bk","fieldId":"booking","operator":"is_not_empty"}],"validation":{"maxLength":500}},{"label":"Your team","required":false,"id":"page-team","type":"page","title":"Your team"},{"label":"Register teammates","required":false,"id":"team","type":"repeater","title":"Register teammates","hint":"Repeating group: add up to five colleagues in one go.","config":{"subFields":[{"id":"tm-name","type":"text","label":"Full name","required":true,"options":[]},{"id":"tm-email","type":"email","label":"Email","required":true,"options":[]},{"id":"tm-role","type":"dropdown","label":"Role","required":false,"options":["Engineering","Design","Product","Operations","Leadership","Other"]}],"minRows":0,"maxRows":5,"addLabel":"Add a teammate"}},{"label":"Speaker or press materials","required":false,"id":"materials","type":"file","title":"Speaker or press materials","hint":"Optional — PDFs or images, up to 3 files of 10 MB each.","config":{"maxFiles":3,"maxSizeMb":10,"accept":".pdf,image/*"}},{"label":"Plan the agenda","required":false,"id":"page-agenda","type":"page","title":"Plan the agenda"},{"label":"Interest per track","required":false,"id":"tracks","type":"matrix","title":"Interest per track","options":["Not for me","Curious","Must attend"],"config":{"rows":["Design systems","AI tooling","Platform engineering","Product strategy"]}},{"label":"Rank what you want more of","required":false,"id":"topics","type":"ranking","title":"Rank what you want more of","options":["Hands-on workshops","Customer case studies","Product roadmap","Community meetups"]},{"label":"Which capabilities are you exploring?","required":false,"id":"interests","type":"multiselect","title":"Which capabilities are you exploring?","hint":"Pick up to three — each adds lead-scoring points.","options":["Form logic","Payments","Workflows & approvals","Analytics","Integrations & API","Security & compliance"],"validation":{"maxSelect":3},"optionPoints":{"Form logic":5,"Payments":5,"Workflows & approvals":5,"Analytics":5,"Integrations & API":5,"Security & compliance":5}},{"label":"How excited are you?","required":true,"id":"excitement","type":"rating","title":"How excited are you?","config":{"max":5}},{"label":"Your excitement index","required":false,"id":"engagement","type":"calculated","title":"Excitement index","formula":"ROUND({How excited are you?} / 5 * 100)","config":{"format":"percent","countInScore":false}},{"label":"Preferred agenda pace","required":false,"id":"pace","type":"scale","title":"Preferred agenda pace","config":{"min":1,"max":7,"minLabel":"Relaxed","maxLabel":"Packed"}},{"label":"How likely are you to recommend the Geiger Summit to a colleague?","required":false,"id":"nps","type":"nps","title":"Recommend","hint":"Shown because you've attended before.","conditions":[{"id":"c-ret","fieldId":"attended-before","operator":"equals","value":"Yes"}],"config":{"minLabel":"Not likely","maxLabel":"Extremely likely"}},{"label":"Warm-up quiz","required":false,"id":"page-quiz","type":"page","title":"Warm-up quiz"},{"label":"Quiz note","required":false,"id":"n-quiz","type":"content","title":"Quiz note","hint":"Quiz mode: these answers are graded when you submit. The pass mark is 70%, and you'll see the correct answers on the thank-you screen."},{"label":"Which field collects a 0–10 recommendation score?","required":false,"id":"quiz-1","type":"select","title":"Which field collects a 0–10 recommendation score?","options":["Star rating","NPS","Linear scale"],"correctAnswer":"NPS","config":{"points":1}},{"label":"Which answers can drive conditional logic?","required":false,"id":"quiz-2","type":"multiselect","title":"Which answers can drive conditional logic?","options":["Text answers","Choice answers","Number answers","Page titles"],"correctAnswer":["Text answers","Choice answers","Number answers"],"config":{"points":2}},{"label":"What is 6 × 7?","required":false,"id":"quiz-3","type":"text","title":"What is 6 × 7?","placeholder":"Type a number","correctAnswer":"42","width":"half","config":{"points":1}},{"label":"Sign & submit","required":false,"id":"page-sign","type":"page","title":"Sign & submit"},{"label":"Signature","required":false,"id":"signature","type":"signature","title":"Signature","hint":"Draw with a mouse, finger or pen — or switch to typing your name."},{"label":"I agree to follow the Geiger Summit code of conduct.","required":true,"id":"consent","type":"checkbox","title":"Code of conduct"},{"label":"Send me product news and next year's early-bird offer.","required":false,"id":"newsletter","type":"checkbox","title":"Newsletter"}]}$j$::jsonb, $j${"theme":{"mode":"dark","accent":"#a855f7","radius":"full","font":"sans","background":"gradient"},"coverStyle":"cover","coverGradient":"plum","coverUrl":"","showIcon":true,"logoUrl":"","branding":true,"layout":"classic","progressBar":true,"locale":"en","welcome":{"enabled":true,"title":"Welcome to the Geiger Summit 2026","body":"Two days of talks, workshops and roadmap previews — November 18–19.\n\nThis registration doubles as a tour of Geiger Forms: payments, bookings, logic, scoring, a quiz and approvals are all switched on.","buttonLabel":"Start registration"},"submitAnother":true,"steps":[],"openDate":"","closeDate":"2027-12-31","closedMessage":"Registration for the Geiger Summit 2026 has closed. Join the waitlist at geiger.dev/summit.","responseLimit":1000,"showResponseLimit":true,"thankYouType":"message","thankYouTitle":"You're registered — see you at the summit!","thankYouText":"Thanks for registering. Your order total is {total} and you've been routed as: {outcome}. Quiz score: {score}.\n\nA confirmation email is on its way, and you can edit your answers for the next 7 days from the link in it.","thankYouUrl":"","showScore":true,"saveResume":true,"offline":true,"confirmEmail":true,"confirmSubject":"Your Geiger Summit 2026 registration","confirmBody":"Hi there,\n\nThanks for registering for the Geiger Summit on behalf of {Company}. Your order total is {total}.\n\nYou've been routed as: {outcome}. We'll email your tickets once your registration is approved.\n\n— The Geiger events team","notifyEmails":["events@example.com"],"notifyFlow":false,"followUps":[{"id":"fu-reminder","delayHours":48,"subject":"Two quick things before the summit","body":"Hi again — book your 1:1 slot and check the agenda before seats fill up. Reply to this email with any questions."},{"id":"fu-week","delayHours":168,"subject":"Your summit checklist","body":"Travel, workshops and the speaker dinner — here's everything you need for {Company}'s visit."}],"reportEmails":["leadership@example.com"],"access":{"mode":"public","orgDomain":"","passwordHash":"","passwordSalt":"","onePerUser":false},"spam":{"honeypot":true,"captcha":false,"rateLimit":30},"anonymous":false,"retentionDays":"","minReviewSeconds":"","duplicates":{"enabled":true,"fieldIds":["email"],"windowDays":60,"action":"flag"},"prefillEnabled":true,"prefill":{"url":true,"user":true},"editWindow":"7d","allowDelegate":true,"attestation":{"enabled":true,"statement":"I confirm the information I've provided is accurate and that I'm authorised to register on behalf of my company."},"policy":{"enabled":true,"title":"Geiger Summit code of conduct","body":"The Geiger Summit is dedicated to a harassment-free experience for everyone, regardless of gender, gender identity and expression, age, sexual orientation, disability, physical appearance, body size, race, ethnicity, religion or technology choices.\n\nWe do not tolerate harassment of participants in any form. Sexual language and imagery is not appropriate for any summit venue, including talks, workshops, parties, social media and other online media.\n\nParticipants asked to stop any harassing behaviour are expected to comply immediately. If a participant engages in harassing behaviour, the organisers may take any action they deem appropriate, including warning the offender or expulsion from the summit with no refund.\n\nIf you are being harassed, notice that someone else is being harassed, or have any other concerns, please contact a member of staff immediately. Staff will be happy to help participants contact venue security or local law enforcement, provide escorts, or otherwise assist those experiencing harassment to feel safe for the duration of the summit.\n\nWe expect participants to follow these rules at all summit venues and summit-related social events.","url":"","requireScroll":true,"requireName":true},"scoringEnabled":true,"highThreshold":55,"mediumThreshold":25,"branchingEnabled":true,"branches":[{"id":"br-enterprise","name":"Enterprise lead","outcome":"Enterprise lead","conditionLogic":"any","conditions":[{"id":"cb-1","fieldId":"budget","operator":"equals","value":"$100k+"},{"id":"cb-2","fieldId":"team-size","operator":"gte","value":"200"}],"priority":"High","status":"Needs review"},{"id":"br-vip","name":"VIP guest","outcome":"VIP guest","conditionLogic":"all","conditions":[{"id":"cb-3","fieldId":"ticket-vip","operator":"equals","value":"true"}],"priority":"Medium"},{"id":"br-online","name":"Online attendee","outcome":"Online attendee","conditionLogic":"all","conditions":[{"id":"cb-4","fieldId":"attendance","operator":"equals","value":"Online"}]},{"id":"br-general","name":"General registration","outcome":"General registration","conditionLogic":"all","conditions":[{"id":"cb-5","fieldId":"attendance","operator":"is_not_empty"}]}],"quiz":{"enabled":true,"passMark":70,"showAnswers":true},"showPollResults":true,"abTest":{"enabled":true,"variants":[{"id":"v-original","name":"Original","title":"","description":""},{"id":"v-urgency","name":"Early-bird urgency","title":"Geiger Summit 2026 — early-bird pricing ends soon","description":"Lock in early-bird pricing, book a 1:1 with our team, and help shape the agenda."}]},"approval":{"enabled":true,"steps":[{"id":"step-ops","name":"Event operations","approvers":["events@example.com"]},{"id":"step-finance","name":"Finance","approvers":["finance@example.com"]}]},"automations":[{"id":"auto-vip","name":"VIP routing","enabled":true,"logic":"all","conditions":[{"id":"ca-1","fieldId":"ticket-vip","operator":"equals","value":"true"}],"actions":[{"type":"add_tag","value":"vip"},{"type":"set_priority","value":"High"},{"type":"assign","value":"Sofia Martins"}]},{"id":"auto-enterprise","name":"Enterprise hand-off","enabled":true,"logic":"any","conditions":[{"id":"ca-2","fieldId":"budget","operator":"equals","value":"$100k+"},{"id":"ca-3","fieldId":"team-size","operator":"gte","value":"200"}],"actions":[{"type":"add_tag","value":"enterprise,sales"},{"type":"assign","value":"Arjun Patel"},{"type":"email","value":"sales@example.com"}]},{"id":"auto-online","name":"Tag online attendees","enabled":true,"logic":"all","conditions":[{"id":"ca-4","fieldId":"attendance","operator":"equals","value":"Online"}],"actions":[{"type":"add_tag","value":"online"}]},{"id":"auto-speaker","name":"Speaker materials","enabled":true,"logic":"all","conditions":[{"id":"ca-5","fieldId":"materials","operator":"is_not_empty"}],"actions":[{"type":"add_tag","value":"speaker"}]}],"flow":{"escalate":true,"when":"outcome","outcome":"Enterprise lead","labels":["form","summit","sales"]},"assets":{"sync":true},"documentTemplate":{"enabled":true,"title":"Registration confirmation — {Company}","body":"This confirms the Geiger Summit 2026 registration for {Full name} of {Company}.\n\nOrder total: {total}. Attendance: {How will you attend?}.\n\nBy signing below, the attendee agrees to the summit code of conduct and the cancellation policy (full refund up to 14 days before the event)."},"payments":{"enabled":true,"currency":"usd","mode":"payment","interval":"month","coupons":[{"code":"EARLYBIRD","type":"percent","value":15,"active":true},{"code":"TEAM50","type":"amount","value":50,"active":true},{"code":"SPRING10","type":"percent","value":10,"active":false}]},"webhooks":[{"id":"wh-crm","url":"https://hooks.example.com/geiger-forms/summit","secret":"whsec_demo_showcase","events":["response.created","response.approved"],"enabled":false}],"slackWebhookUrl":"","sharing":[{"email":"maya.chen@example.com","role":"admin"},{"email":"sofia.martins@example.com","role":"editor"},{"email":"finance@example.com","role":"viewer"}],"template":null}$j$::jsonb, false, now() - interval '74880 minutes', now() - interval '180 minutes', now() - interval '66240 minutes', null)
