insert into forms.versions (id, form_id, version, label, author, notes, schema, settings, created_at) values
  ('4cda75d6-943c-44fa-ade6-033af419a429', '343ba6d4-7ee9-4a33-aa8c-f46e26e8d3c2', 1, 'Initial draft', 'Maya Chen', 'About-you page and logistics.', $j${"fields":[{"label":"About you","required":false,"id":"h-about","type":"heading","title":"About you","hint":"Start with the basics. Every input validates as you type."},{"label":"Showcase note","required":false,"id":"n-welcome","type":"content","title":"Showcase note","hint":"This form is the Geiger Forms feature showcase. Each page highlights a different capability — look for notes like this one. The look itself (round corners, purple accent, gradient background and cover) is set in the builder Design panel.\n\nOn this page: name, email, phone, URL and number fields, half/third-width layouts, info tooltips, a read-only field prefilled from the link (?member=GS-1042) and hidden UTM fields."},{"label":"Full name","required":true,"id":"full-name","type":"name","title":"Full name"},{"label":"Work email","required":true,"id":"email","type":"email","title":"Work email","placeholder":"you@company.com","width":"half","info":"We send your tickets and calendar invites here. Duplicate registrations with the same email are flagged for review."},{"label":"Mobile number","required":false,"id":"phone","type":"phone","title":"Mobile number","placeholder":"+1 555 010 0100","width":"half","hint":"Only used for day-of-event updates."},{"label":"Company","required":true,"id":"company","type":"text","title":"Company","width":"half","validation":{"minLength":2,"maxLength":80}},{"label":"Company website","required":false,"id":"website","type":"url","title":"Company website","placeholder":"https://","width":"half"},{"label":"Your role","required":true,"id":"role","type":"dropdown","title":"Your role","options":["Engineering","Design","Product","Operations","Leadership","Other"],"width":"third"},{"label":"Team size","required":false,"id":"team-size","type":"number","title":"Team size","placeholder":"e.g. 25","width":"third","validation":{"min":1,"max":100000}},{"label":"Annual tooling budget","required":false,"id":"budget","type":"dropdown","title":"Annual tooling budget","options":["Under $10k","$10k–$50k","$50k–$100k","$100k+"],"width":"third","info":"Each option carries lead-scoring points.","optionPoints":{"Under $10k":0,"$10k–$50k":15,"$50k–$100k":30,"$100k+":50}},{"label":"Have you attended a Geiger Summit before?","required":true,"id":"attended-before","type":"select","title":"Have you attended a Geiger Summit before?","options":["Yes","No"]},{"label":"Member ID","required":false,"id":"member-id","type":"text","title":"Member ID","readOnly":true,"prefillKey":"member","hint":"Read-only — prefilled from the invite link (?member=…)."},{"label":"UTM source","required":false,"id":"utm-source","type":"hidden","title":"UTM source","prefillKey":"utm_source","defaultValue":"direct"},{"label":"UTM campaign","required":false,"id":"utm-campaign","type":"hidden","title":"UTM campaign","prefillKey":"utm_campaign"}]}$j$::jsonb, $j${"theme":{"mode":"dark","accent":"#6366f1","radius":"md","font":"sans","background":"plain"},"coverStyle":"cover","coverGradient":"ocean","coverUrl":"","showIcon":true,"logoUrl":"","branding":true,"layout":"classic","progressBar":true,"locale":"en","welcome":{"enabled":true,"title":"Welcome to the Geiger Summit 2026","body":"Two days of talks, workshops and roadmap previews — November 18–19.\n\nThis registration doubles as a tour of Geiger Forms: payments, bookings, logic, scoring, a quiz and approvals are all switched on.","buttonLabel":"Start registration"},"submitAnother":true,"steps":[],"openDate":"","closeDate":"2027-12-31","closedMessage":"Registration for the Geiger Summit 2026 has closed. Join the waitlist at geiger.dev/summit.","responseLimit":1000,"showResponseLimit":true,"thankYouType":"message","thankYouTitle":"You're registered — see you at the summit!","thankYouText":"Thanks for registering. Your order total is {total} and you've been routed as: {outcome}. Quiz score: 