venue, including talks, workshops, parties, social media and other online media.\n\nParticipants asked to stop any harassing behaviour are expected to comply immediately. If a participant engages in harassing behaviour, the organisers may take any action they deem appropriate, including warning the offender or expulsion from the summit with no refund.\n\nIf you are being harassed, notice that someone else is being harassed, or have any other concerns, please contact a member of staff immediately. Staff will be happy to help participants contact venue security or local law enforcement, provide escorts, or otherwise assist those experiencing harassment to feel safe for the duration of the summit.\n\nWe expect participants to follow these rules at all summit venues and summit-related social events.","url":"","requireScroll":true,"requireName":true},"scoringEnabled":true,"highThreshold":55,"mediumThreshold":25,"branchingEnabled":true,"branches":[{"id":"br-enterprise","name":"Enterprise lead","outcome":"Enterprise lead","conditionLogic":"any","conditions":[{"id":"cb-1","fieldId":"budget","operator":"equals","value":"$100k+"},{"id":"cb-2","fieldId":"team-size","operator":"gte","value":"200"}],"priority":"High","status":"Needs review"},{"id":"br-vip","name":"VIP guest","outcome":"VIP guest","conditionLogic":"all","conditions":[{"id":"cb-3","fieldId":"ticket-vip","operator":"equals","value":"true"}],"priority":"Medium"},{"id":"br-online","name":"Online attendee","outcome":"Online attendee","conditionLogic":"all","conditions":[{"id":"cb-4","fieldId":"attendance","operator":"equals","value":"Online"}]},{"id":"br-general","name":"General registration","outcome":"General registration","conditionLogic":"all","conditions":[{"id":"cb-5","fieldId":"attendance","operator":"is_not_empty"}]}],"quiz":{"enabled":false},"showPollResults":true,"abTest":{"enabled":true,"variants":[{"id":"v-original","name":"Original","title":"","description":""},{"id":"v-urgency","name":"Early-bird urgency