  ('4b30153d-7861-4ee3-ab3b-d904a85b68ea', '343ba6d4-7ee9-4a33-aa8c-f46e26e8d3c2', 5, 'Design refresh', 'Sofia Martins', 'Restyled in the builder Design panel: round corners, purple accent, accent-tinted gradient background and the plum cover.', $j${"fields":[{"label":"About you","required":false,"id":"h-about","type":"heading","title":"About you","hint":"Start with the basics. Every input validates as you type."},{"label":"Showcase note","required":false,"id":"n-welcome","type":"content","title":"Showcase note","hint":"This form is the Geiger Forms feature showcase. Each page highlights a different capability — look for notes like this one. The look itself (round corners, purple accent, gradient background and cover) is set in the builder Design panel.\n\nOn this page: name, email, phone, URL and number fields, half/third-width layouts, info tooltips, a read-only field prefilled from the link (?member=GS-1042) and hidden UTM fields."},{"label":"Full name","required":true,"id":"full-name","type":"name","title":"Full name"},{"label":"Work email","required":true,"id":"email","type":"email","title":"Work email","placeholder":"you@company.com","width":"half","info":"We send your tickets and calendar invites here. Duplicate registrations with the same email are flagged for review."},{"label":"Mobile number","required":false,"id":"phone","type":"phone","title":"Mobile number","placeholder":"+1 555 010 0100","width":"half","hint":"Only used for day-of-event updates."},{"label":"Company","required":true,"id":"company","type":"text","title":"Company","width":"half","validation":{"minLength":2,"maxLength":80}},{"label":"Company website","required":false,"id":"website","type":"url","title":"Company website","placeholder":"https://","width":"half"},{"label":"Your role","required":true,"id":"role","type":"dropdown","title":"Your role","options":["Engineering","Design","Product","Operations","Leadership","Other"],"width":"third"},{"label":"Team size","required":false,"id":"team-s